import{_ as c,C as n,o as l,c as h,a3 as u,E as a,w as r,j as o,a as t}from"./chunks/framework.B02wg2PO.js";const y=JSON.parse('{"title":"Your First Run","description":"","frontmatter":{},"headers":[],"relativePath":"quickstart/first-run.md","filePath":"quickstart/first-run.md"}'),p={name:"quickstart/first-run.md"};function g(m,e,f,b,w,k){const s=n("Callout"),d=n("Card"),i=n("CardGrid");return l(),h("div",null,[e[4]||(e[4]=u('<h1 id="your-first-run" tabindex="-1">Your First Run <a class="header-anchor" href="#your-first-run" aria-label="Permalink to &quot;Your First Run&quot;">​</a></h1><p>A <strong>Run</strong> is the durable unit of delegated work. This page takes one from brief to verified result.</p><h2 id="_1-start-it" tabindex="-1">1. Start it <a class="header-anchor" href="#_1-start-it" aria-label="Permalink to &quot;1. Start it&quot;">​</a></h2><p>Two ways in:</p><ul><li><strong>From chat</strong> — describe the objective to PRIME. If it is more than a one-shot question, PRIME calls <code>start_run</code> and you get a Run with its own thread.</li><li><strong>From the Runs view</strong> — the <em>New Run</em> dialog lets you set the brief, the target project, the effort mode, and the execution mode up front.</li></ul><p>A good brief names the objective and how you will know it worked:</p><blockquote><p>Add rate limiting to the public webhook endpoint. Done when <code>npm test</code> passes and a new test covers the 429 path.</p></blockquote><h2 id="_2-watch-the-plan-freeze" tabindex="-1">2. Watch the plan freeze <a class="header-anchor" href="#_2-watch-the-plan-freeze" aria-label="Permalink to &quot;2. Watch the plan freeze&quot;">​</a></h2><p>PRIME&#39;s first act is to set the checklist. Each <code>ChecklistItem</code> carries:</p><ul><li><code>text</code> — the task</li><li><code>assignee</code> — the project or agent responsible</li><li><code>dependsOn</code> — other task ids that must finish first</li><li><code>mode</code> — <code>ask</code> (read-only investigation) or <code>work</code> (writes)</li><li><code>acceptanceCriteria</code> — what the verifier will rule on</li><li><code>checks</code> / <code>proofs</code> — optional mechanical proof</li></ul><p>The plan is stamped into <code>originalChecklist</code>, so any later amendment is visible as drift rather than silently overwriting history.</p><div class="tip custom-block"><p class="custom-block-title">Guided vs autonomous</p><p><strong>Guided</strong> (<code>executionMode: &#39;guided&#39;</code>) — the engine picks ready tasks from the frozen plan, batches independent ones, and only advances on a passed verdict. Use it for repeatable work. <strong>Autonomous</strong> — PRIME decides each step, and can re-plan mid-flight. Use it for genuinely exploratory work.</p></div><h2 id="_3-follow-the-thread" tabindex="-1">3. Follow the thread <a class="header-anchor" href="#_3-follow-the-thread" aria-label="Permalink to &quot;3. Follow the thread&quot;">​</a></h2><p>The Run thread is an ordered list of <code>RunEvent</code>s. Each has an <code>actor</code> (<code>OPERATOR</code>, <code>PRIME</code>, a project/agent name, or <code>SYSTEM</code>) and a <code>kind</code>:</p><table tabindex="0"><thead><tr><th>kind</th><th>Meaning</th></tr></thead><tbody><tr><td><code>message</code></td><td>A normal message</td></tr><tr><td><code>delegation</code></td><td>PRIME handed work to an agent</td></tr><tr><td><code>question</code></td><td>An agent asked something back</td></tr><tr><td><code>answer</code></td><td>The resolved answer</td></tr><tr><td><code>tool</code> / <code>result</code></td><td>A tool step and its output</td></tr><tr><td><code>system</code></td><td>A branch cut, a pause, a cap reached</td></tr></tbody></table><p>Every committed message carries its own <code>stats</code> — input/output tokens, cache reads, duration, context occupancy, cost, and the model that served it.</p><h2 id="_4-answer-when-it-asks" tabindex="-1">4. Answer when it asks <a class="header-anchor" href="#_4-answer-when-it-asks" aria-label="Permalink to &quot;4. Answer when it asks&quot;">​</a></h2><p>A Run at <code>awaiting_input</code> is blocked on you. Two shapes:</p><ul><li><strong>A question.</strong> Reply in the run thread; PRIME relays it to the agent that asked.</li><li><strong>An approval gate.</strong> If the target project&#39;s policy is <code>approval: confirm</code>, a write parks as a <code>PendingApproval</code> naming the exact project, the exact change, and the question. Approving re-runs that precise delegation with <code>approved: true</code> — it is not a guess at what &quot;yes&quot; meant.</li></ul><h2 id="_5-read-the-result" tabindex="-1">5. Read the result <a class="header-anchor" href="#_5-read-the-result" aria-label="Permalink to &quot;5. Read the result&quot;">​</a></h2><p>When PRIME reports the objective met, the Run goes <code>done</code>. What you have:</p><ul><li><strong>A branch.</strong> Default policy cuts a <code>saidi/*</code> branch and opens a PR; <code>branch: current</code> commits on the checked-out branch instead.</li><li><strong>Evidence.</strong> The engine collects it off git — base ref, commits, files with additions/deletions — plus any command it ran with its exit code.</li><li><strong>A usage ledger.</strong> One entry per settled LLM call: actor, models, tokens, cost, duration.</li><li><strong>A verification log.</strong> Append-only, run-level, and it outlives plan amendments.</li></ul><h2 id="statuses" tabindex="-1">Statuses <a class="header-anchor" href="#statuses" aria-label="Permalink to &quot;Statuses&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Status</th><th>Meaning</th></tr></thead><tbody><tr><td><code>active</code></td><td>PRIME or a delegated agent is working</td></tr><tr><td><code>awaiting_input</code></td><td>Blocked on your reply</td></tr><tr><td><code>paused</code></td><td>Stopped but resumable</td></tr><tr><td><code>done</code></td><td>PRIME reported the objective met</td></tr><tr><td><code>error</code></td><td>A turn failed</td></tr><tr><td><code>cancelled</code></td><td>You stopped it</td></tr></tbody></table>',24)),a(s,{type:"success",title:"You know the Run worked when…"},{default:r(()=>[...e[0]||(e[0]=[o("p",null,[t("The plan shows every task at "),o("code",null,"done"),t(", the verification log has an entry per criterion with a check the Run did not author, and "),o("code",null,"git log"),t(" on the "),o("code",null,"saidi/*"),t(" branch shows the commits. Anything less is a report, not a result.")],-1)])]),_:1}),e[5]||(e[5]=o("h2",{id:"where-to-go-next",tabindex:"-1"},[t("Where to go next "),o("a",{class:"header-anchor",href:"#where-to-go-next","aria-label":'Permalink to "Where to go next"'},"​")],-1)),a(i,{cols:3},{default:r(()=>[a(d,{title:"Connect a repo",icon:"branch",href:"/quickstart/connecting-a-repo",cta:"Connecting a Repo"},{default:r(()=>[...e[1]||(e[1]=[t(" Register a project so agents get a scoped checkout, a policy, and a verify command. ",-1)])]),_:1}),a(d,{title:"Set your guardrails",icon:"shield",href:"/guides/guardrails",cta:"Guardrails"},{default:r(()=>[...e[2]||(e[2]=[t(" Approval mode and spend limits, decided before the first autonomous Run rather than during it. ",-1)])]),_:1}),a(d,{title:"Drive Runs from chat",icon:"channel",href:"/guides/managing-runs",cta:"Managing Runs"},{default:r(()=>[...e[3]||(e[3]=[t(" Steer, approve, pause and stop a Run from the web app or from Telegram. ",-1)])]),_:1})]),_:1})])}const R=c(p,[["render",g]]);export{y as __pageData,R as default};
